{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "Records were eligible for inclusion if they met the following criteria: - (i) the use of at least one POC testing device assessing NCD measures, including cardiovascular disease (e.g. lipid profiles, coagulation markers), chronic respiratory disease (e.g. FeNO), or diabetes (e.g. HbA1c, blood glucose). POC testing was considered across multiple contexts, including adult care, paediatric care, self-managed testing, clinic-based testing, or community health settings; - (ii) reporting of at least one measure related to health literacy or health literacy responsiveness, including outcomes mapped to the five WHO health literacy actions ( Access , Understand , Appraise , Remember , Use ). This could include direct assessment of health literacy using validated instruments, or proxy measures such as patient activation, knowledge, awareness, confidence, satisfaction, engagement, behaviour change, or relevant clinical indicators; - (iii) health literacy of individuals aged 10 + years, including older children and adolescents, with caregivers able to report their own health literacy outcomes based on POC assessment of a child; - (iv) full-text peer reviewed journal article published within the five years prior to the search.",
      "reason": "Eligibility components for participants/setting (adult, paediatric, self-managed, clinic-based, community), eligible interventions/POC devices (NCD measures), and health literacy constructs (mapped to WHO actions) are specified, and study publication type/design restrictions are addressed (no restrictions on study design). However, follow-up requirements for included studies are not mentioned."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "full-text peer reviewed journal article published within the five years prior to the search. Studies were excluded if they were reviews of peerreviewed studies. The five-year limit was applied in line with WHO guidance to capture contemporary evidence on POC testing and health literacy, reflecting advances in diagnostic technologies and evolving definitions of health literacy. No restrictions on the type of study design, sample size, or language of manuscript were imposed.",
      "reason": "Report characteristics are specified: full-text peer-reviewed journal articles; publication within the five years prior to the search; exclusion of review articles; and no restrictions on manuscript language. Follow-up status/publication status beyond these points is not required by the criterion and is not stated as needed here."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence is provided that the review distinguishes exclusion due to outcomes not being measured versus exclusion due to outcome results not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "callout_0",
      "quote": "Despite this, shared self-reported proxy outcomes such as patient knowledge, confidence, engagement, and behaviour change enabled narrative synthesis via the framework of WHO health literacy actions.",
      "reason": "The synthesis framework/grouping by WHO health literacy actions is specified for narrative synthesis. However, the evidence provided does not clearly link these groups to the specific comparisons defined in the review objectives (comparisons are not described in the retrieved material)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The five-year limit was applied in line with WHO guidance to capture contemporary evidence on POC testing and health literacy, reflecting advances in diagnostic technologies and evolving definitions of health literacy.",
      "reason": "A rationale is explicitly provided for a notable eligibility restriction (the five-year publication limit)."
    }
  ],
  "confidence": 78
}

